    val MAP: Map<String, DuaText> = mapOf(
        "dua_sajdah_tilawah" to DuaText("Sajdah della recitazione", "Il mio volto si è prostrato a Colui che lo ha creato e ne ha prodotto l'udito e la vista con la Sua potenza e potenza.", "Nella prostrazione della recitazione.", "Il Profeta ﷺ lo disse nella prostrazione della recitazione notturna."),
        "dua_after_witr" to DuaText("Dopo Witr", "Gloria al Re, il Santissimo.", "Tre volte dopo il salam del witr, alzando la voce per la terza volta.", "Il Profeta ﷺ disse questo dopo witr."),
        "dua_tahajjud_nur" to DuaText("Supplica di apertura di Tahajjud", "O Allah, a Te appartiene la lode; Tu sei il Sostenitore dei cieli, della terra e di tutto ciò che è in essi. A te appartiene la lode; Tu sei la Luce dei cieli, della terra e di tutto ciò che è in essi. A te appartiene la lode; Tu sei la Verità, la Tua promessa è vera, l'incontro con Te è vero, la Tua parola è vera, il Paradiso è vero, l'Inferno è vero, i Profeti sono veri, Muhammad ﷺ è vero e l'Ora è vera.", "Quando si inizia la preghiera notturna (tahajjud) (la parte iniziale del dua).", "Il Profeta ﷺ lo recitò alzandosi per tahajjud (il dua completo è in al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Guidami nelle questioni controverse", "O Allah, Signore di Jibril, Mika'il e Israfil, Creatore dei cieli e della terra, Conoscitore dell'invisibile e del visto! Giudicherai tra i tuoi servi in ​​che cosa differivano. Guidami con il tuo permesso alla verità su ciò su cui ho discusso. In verità tu guidi chi vuoi sulla retta via.", "All’inizio del tahajjud – per orientarsi verso la verità in mezzo al disaccordo.", "Il Profeta ﷺ iniziò la sua preghiera notturna con questo dua."),
        "dua_going_to_mosque_nur" to DuaText("Andare alla Moschea (Dua di Luce)", "O Allah, metti la luce nel mio cuore, la luce nei miei occhi, la luce nelle mie orecchie, la luce alla mia destra, la luce alla mia sinistra, la luce sopra di me, la luce sotto di me, la luce davanti a me, la luce dietro di me e fai luce per me.", "Mentre andavo alla moschea per Fajr.", "Il Profeta ﷺ lo recitava quando usciva per la preghiera."),
        "dua_waswasa_salah" to DuaText("Waswasa durante Salah (Khinzab)", "Cerco rifugio in Allah da Shaytan, il maledetto.", "Quando durante la preghiera arrivano sussurri satanici, cerca rifugio e sputa leggermente a sinistra tre volte.", "Uthman ibn Abil-'As (RA) fece questo e i sussurri sparirono."),
        "dua_alimal_ghayb" to DuaText("Conoscitore dell'Invisibile", "O Allah, Conoscitore dell'invisibile e del visto, Creatore dei cieli e della terra, Signore e Sovrano di tutte le cose! Attesto che non c'è altro dio all'infuori di Te. Cerco rifugio in Te dal male di me stesso e dal male di Shaytan e dalla sua (chiamata a) shirk.", "Mattina, sera e prima di dormire: il Profeta ﷺ lo insegnò ad Abu Bakr (RA).", "Protezione dal male di sé e di Shaytan."),
        "dua_fitratil_islam" to DuaText("Sulla Fitrah dell'Islam", "Siamo entrati nel mattino sulla fitrah dell'Islam, sulla parola di sincerità, sulla religione del nostro profeta Muhammad ﷺ e sulla via di nostro padre Ibrahim (AS), che era retto e musulmano e non era un politeista.", "La mattina.", "Rinnovare la propria fede ogni mattina."),
        "dua_amsayna_fitrah" to DuaText("Serata sulla Fitrah dell'Islam", "Siamo entrati nella sera sulla fitrah dell'Islam, sulla parola di sincerità, sulla religione del nostro profeta Muhammad ﷺ e sulla via di nostro padre Ibrahim (AS), che era retto e musulmano e non era un politeista.", "In serata.", "Rinnovare la fede ogni sera."),
        "dua_tahleel_10_fajr" to DuaText("Dieci Tahleel dopo Fajr e Maghrib", "Nessuno ha il diritto di essere adorato tranne Allah, da solo, senza partner. Suo è il dominio e Sua è la lode; Dà la vita e causa la morte e ha potere su tutte le cose.", "Dieci volte dopo Fajr (e Maghrib), prima di alzarti dalla posizione seduta o dal parlare.", "Dieci buone azioni, dieci peccati cancellati, dieci gradi elevati e protezione da Shaytan tutto il giorno."),
        "dua_la_hawla_kanz" to DuaText("Un tesoro di Jannah", "Non c'è forza né potere se non presso Allah.", "Spesso, in ogni momento.", "È uno dei tesori del Paradiso."),
        "dua_four_beloved_words" to DuaText("Le quattro parole più amate", "Gloria ad Allah, ogni lode è per Allah, nessuno ha il diritto di essere adorato tranne Allah, e Allah è il Più Grande.", "Le parole più amate da Allah.", "Sono più cari al Profeta ﷺ di tutto ciò su cui sorge il sole."),
        "dua_two_light_words" to DuaText("Due parole illuminano la lingua", "Gloria ad Allah e ogni lode è Sua; gloria ad Allah, il Magnifico.", "Leggero sulla lingua, pesante sulla bilancia.", "Amato dal Misericordioso, leggero sulla lingua e pesante sulla bilancia. (L'ultimo hadith di al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "O Possessore di maestà e onore!", "Tenetelo stretto in dua: l'istruzione ﷺ del Profeta.", "Il Profeta ﷺ disse: aggrappati a 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("Nel tuo nome mi corico", "Nel tuo nome, mio ​​Signore, mi sdraio e nel tuo nome mi alzo. Se prendi la mia anima, abbi pietà di essa, e se la liberi, proteggila come proteggi i Tuoi servitori giusti.", "Dopo aver spolverato il letto e essermi sdraiato.", "Affidare la propria anima ad Allah prima di dormire."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Hai creato la mia anima", "O Allah, hai creato la mia anima e la prenderai. La sua morte e la sua vita appartengono a Te. Se lo mantieni in vita, proteggilo, e se lo fai morire, perdonalo. O Allah, ti chiedo il benessere.", "Prima di dormire - narrato da Ibn Umar (RA).", "Il Profeta ﷺ ordinò di dirlo prima di andare a dormire."),
        "dua_sleep_atamana" to DuaText("Gratitudine prima del sonno", "Ogni lode è per Allah che ci ha nutrito, ci ha dato da bere, ci ha saziato e ci ha dato rifugio. Quanti sono che non hanno nessuno che gli basti o che dia loro riparo.", "Quando vado a letto.", "Il Profeta ﷺ lo disse mentre andava a letto."),
        "dua_sleep_rabbas_samawat" to DuaText("Signore dei Cieli: Paga il nostro debito", "O Allah, Signore dei cieli, della terra e del Possente Trono, nostro Signore e Signore di tutte le cose, Divisore del seme e del dattero, Rivelatore della Torah, dell'Injil e del Furqan! Mi rifugio in te dal male di tutto ciò di cui tieni il ciuffo. O Allah, Tu sei il Primo, non c'è nulla prima di Te; Tu sei l'Ultimo, non c'è niente dopo di Te; Tu sei il Manifesto, non c'è nulla al di sopra di Te; Tu sei il Nascosto, non c'è nulla che ti sia nascosto. Salda per noi il nostro debito e liberaci dalla povertà.", "Prima di dormire, sdraiato sul lato destro – insegnato a Fatimah (RA).", "Un dua per alleviare i debiti e le difficoltà."),
        "dua_sleep_fear" to DuaText("Paura o disagio nel sonno", "Cerco rifugio nelle perfette parole di Allah dalla Sua ira e dalla Sua punizione, dalla malvagità dei Suoi servi e dai sussurri dei diavoli e dalla loro venuta da me.", "Quando si prova paura o disagio nel sonno.", "Così facendo, quella cosa non gli farà del male."),
        "dua_waking_afani" to DuaText("Risveglio: ha restaurato la mia anima", "Ogni lode è per Allah che ha dato il benessere al mio corpo, mi ha restituito la mia anima e mi ha permesso di ricordarLo.", "Al risveglio.", "Gratitudine per un nuovo mattino."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah è il mio Signore", "Allah, Allah è il mio Signore; Non associo nulla a Lui.", "Nel dolore o nell'angoscia: il Profeta ﷺ lo insegnò ad Asma bint Umays (RA).", "Aggrapparsi al tawhid nei momenti di angoscia."),
        "dua_rahmataka_arju" to DuaText("Spero nella tua misericordia", "O Allah, è nella Tua misericordia che spero, quindi non lasciarmi solo per un batter d'occhio e metti a posto tutti i miei affari. Non c'è altro Dio all'infuori di Te.", "Il dua di chi è in difficoltà (Da'awat al-makrub).", "Il Profeta ﷺ lo chiamò dua di chi è in difficoltà."),
        "dua_against_enemy_ahzab" to DuaText("Contro gli eserciti nemici", "O Allah, Rivelatore del Libro, Veloce nel fare i conti! Sconfiggi i confederati. O Allah, sconfiggili e scuotili.", "Contro il nemico: il dua della Battaglia dei Confederati.", "Il dua ﷺ del Profeta contro il nemico."),
        "dua_anta_adudi" to DuaText("Tu sei il mio sostegno", "O Allah, Tu sei il mio sostegno e il mio aiuto. Con te pianifico, con te avanzo e con te combatto.", "Prima di una gara o di una sfida importante.", "Il Profeta ﷺ lo disse in battaglia."),
        "dua_ikfinihim" to DuaText("Mi basta contro di loro", "O Allah, basti contro di loro, come preferisci.", "Contro il male degli oppressori: il dua del ragazzo nella storia della Gente del Fosso.", "Allah ha salvato il ragazzo dagli oppressori."),
        "dua_qadarullah" to DuaText("Quando succede qualcosa di brutto", "È il decreto di Allah, ed Egli ha fatto ciò che ha voluto.", "Quando succede qualcosa di spiacevole, invece di dire \"se solo\".", "\"Se solo\" apre la porta a Shaytan."),
        "dua_ala_kulli_hal" to DuaText("Lode in ogni situazione", "Ogni lode è per Allah in ogni situazione.", "Quando succede qualcosa che non piace.", "Il Profeta ﷺ disse questo di fronte a qualcosa che non gli piaceva."),
        "dua_dogs_barking" to DuaText("Sentire i cani abbaiare di notte", "Cerco rifugio in Allah da Shaytan, il maledetto.", "Sentendo i cani abbaiare o il raglio di un asino di notte.", "Vedono ciò che tu non vedi."),
        "dua_leaving_home_adilla" to DuaText("Rifugio dallo smarrimento", "O Allah, mi rifugio in Te per timore di andare fuori strada o di essere sviato, per timore di scivolare o di essere fatto scivolare, per timore di fare qualcosa di sbagliato o di subire un torto, per timore di comportarmi stupidamente o di essere trattato stupidamente.", "Quando esci di casa - narrato da Umm Salamah (RA).", "Il Profeta ﷺ recitava questo ogni volta che usciva di casa."),
        "dua_ascending_descending" to DuaText("Salire e scendere", "Allah è il più grande (quando sale). — Gloria ad Allah (quando scendi).", "Durante un viaggio, dire \"Allahu Akbar\" quando si sale e \"SubhanAllah\" quando si scende.", "La pratica dei Compagni (RA) in viaggio."),
        "dua_traveller_sahar" to DuaText("Dua del viaggiatore prima dell'alba", "Un ascoltatore ha ascoltato (e trasmesso) la nostra lode ad Allah e i Suoi favori su di noi. Nostro Signore, accompagnaci e concedici il tuo favore - (dico questo) cercando rifugio in Allah dal Fuoco.", "In viaggio, prima dell'alba.", "Il Profeta ﷺ lo disse prima dell'alba mentre era in viaggio."),
        "dua_zawwadakallah" to DuaText("Al viaggiatore: Che Allah fornisca Taqwa", "Possa Allah fornirti la taqwa per il tuo viaggio, perdonare i tuoi peccati e renderti facile il bene ovunque tu sia.", "Quando si saluta un viaggiatore.", "Il Profeta ﷺ diede questo dua a qualcuno che intraprendeva un viaggio."),
        "dua_traveller_to_resident" to DuaText("Viaggiatore verso coloro che restano indietro", "Ti affido ad Allah, presso il quale la fiducia non viene mai persa.", "Detto dal viaggiatore nel salutare la famiglia.", "Affidare ad Allah la sicurezza della famiglia."),
        "dua_entering_village" to DuaText("Entrare in una città o villaggio", "O Allah, Signore dei sette cieli e di tutto ciò che essi ombreggiano, Signore delle sette terre e di tutto ciò che portano, Signore dei diavoli e di tutto ciò che sviano, Signore dei venti e di tutto ciò che disperdono! Ti chiediamo il bene di questa città e il bene della sua gente, e cerchiamo rifugio in Te dal suo male, dal male della sua gente e dal male di ciò che c'è in essa.", "Prima di entrare in un paese o città.", "Il Profeta ﷺ lo recitava ogni volta che desiderava entrare in una città."),
        "dua_vehicle_stumbles" to DuaText("Quando il veicolo inciampa", "Nel nome di Allah.", "Quando la cavalcatura o il veicolo scivola o inciampa, invece di dire \"Che Shaytan muoia\".", "Dire Bismillah fa rimpicciolire Shaytan fino alle dimensioni di una mosca."),
        "dua_ajz_kasal_haram" to DuaText("Rifugio dalla debolezza e dalla vecchiaia", "O Allah, cerco rifugio in Te dall'impotenza e dalla pigrizia, dalla codardia e dalla vecchiaia, dalle prove della vita e della morte e dalla punizione della tomba.", "Un dua quotidiano completo di rifugio.", "Un dua che il Profeta ﷺ faceva spesso."),
        "dua_sharri_ma_amiltu" to DuaText("Rifugio dalla malvagità delle Mie Azioni", "O Allah, mi rifugio in Te dal male di ciò che ho fatto e dal male di ciò che non ho fatto.", "Un dua del Profeta ﷺ, secondo Aisha (RA).", "Protezione dalle conseguenze sia di ciò che è stato fatto sia di ciò che è stato lasciato incompiuto."),
        "dua_jahdil_bala" to DuaText("Rifugio dalle dure prove", "O Allah, mi rifugio in Te dalle dure prove, dall'essere sopraffatto dalla miseria, da un decreto malvagio e dall'esultanza dei nemici.", "Rifugio dalle dure prove e dall'esultanza dei nemici.", "Il Profeta ﷺ cercò rifugio da queste quattro cose."),
        "dua_fitnat_ghina_faqr" to DuaText("Rifugio dalle prove della ricchezza e della povertà", "O Allah, cerco rifugio in Te dalla pigrizia e dalla vecchiaia, dal peccato e dai debiti, dalla prova e dalla punizione della tomba, dalla prova e dalla punizione del Fuoco, dal male della prova della ricchezza e dalla prova della povertà.", "Rifugio dalle prove della tomba, Inferno, ricchezza e povertà (parte del dua).", "Un dua completo di rifugio dal Profeta ﷺ."),
        "dua_kufr_faqr" to DuaText("Rifugio dall'incredulità e dalla povertà", "O Allah, cerco rifugio in Te dall'incredulità e dalla povertà, e cerco rifugio in Te dalla punizione della tomba. Non c'è altro Dio all'infuori di Te.", "Tre volte mattina e sera.", "Abu Bakrah (RA) sentì dire questo dal Profeta ﷺ."),
    )
}
